  evDup(t) { const e = clone(evById(t.dataset.id)); ui.pop = null; e.id = uid('e'); e.title += ' (copy)'; e.status = 'draft'; e.regs = []; e.invites = []; e.date = addDays(TODAY, 30); S.events.push(e); persist(); toast('Duplicated as a draft. Registrations weren’t copied.'); go('event-' + e.id); },
